const $=s=>document.querySelector(s);
const lessons=[
{title:'The everyday workflow',nav:'Git fundamentals',description:'From a small change to a saved snapshot. Learn the three places your code lives.',duration:3,steps:[['Make a change','Edit a file','edit pancakes.txt'],['Stage your change','git add pancakes.txt','git add pancakes.txt'],['Save a snapshot','git commit','git commit -m "Add chocolate chips"'],['Share your work','git push','git push origin main']],insight:['The mental model','Edit → stage → commit. You choose exactly what goes into each snapshot.'],hint:'A commit is a snapshot. A branch is a pointer to one.'},
{title:'A parallel universe',nav:'Branches & merging',description:'Try an idea on its own branch, then bring it back into main.',duration:4,steps:[['Create a branch','git switch -c feature','git switch -c feature'],['Build your idea','Edit, stage & commit','build-feature'],['Return to main','git switch main','git switch main'],['Bring it together','git merge feature','git merge feature']],insight:['A branch is a pointer','Branches share history. They don’t copy an entire project. HEAD tracks the branch you are working on.'],hint:'Make space for an idea without disturbing main.'},
{title:'Local meets remote',nav:'GitHub & remotes',description:'Your machine and GitHub have separate copies. Keep them in sync deliberately.',duration:3,steps:[['A teammate pushes','A new remote snapshot','remote-change'],['Look for updates','git fetch origin','git fetch origin'],['Bring updates into main','git merge origin/main','git merge origin/main'],['Publish your next change','Edit, commit & push','publish-change']],insight:['Fetch ≠ pull','Fetch downloads history and updates origin/main. Pull fetches, then integrates using merge or rebase.'],hint:'Git works locally. GitHub hosts a remote repository.'},
{title:'Better, together',nav:'Team collaboration',description:'You, Maya, and Leo share one project. Propose a feature, review it, and merge it.',duration:5,steps:[['Start your feature','git switch -c feature','git switch -c feature'],['Push your work','Commit & publish branch','team-push'],['Open a pull request','Propose feature → main','open-pr'],['Get a teammate’s review','Maya approves the change','review-pr'],['Merge on GitHub','A merge commit joins histories','merge-pr'],['Update your local copy','git pull --ff-only origin main','team-pull']],insight:['People behind the pointers','A pull request is a GitHub conversation about a proposed change. Reviews help a team decide what to merge.'],hint:'Each person has their own local repository. GitHub is the shared meeting point.'},
{title:'Two edits. One decision.',nav:'Merge conflicts',description:'You and Maya changed the same line. Decide what the finished file should say.',duration:4,steps:[['Try to merge','git merge feature','git merge feature'],['Resolve the line','Choose a result below the graph','resolve-conflict'],['Stage the resolved file','git add pancakes.txt','git add pancakes.txt'],['Finish the merge','git commit','git commit -m "Agree on sugar amount"']],insight:['Conflicts are a conversation','Git asks for a decision when it cannot combine changes automatically. Resolve the file, stage it, then commit.'],hint:'Both histories are safe. Choose the final content before finishing the merge.'},
{title:'A safe way back',nav:'Undo & recovery',description:'Undo a published mistake while keeping the shared history intact.',duration:3,steps:[['Inspect the latest change','git show HEAD','git show HEAD'],['Undo with a new commit','git revert HEAD','git revert HEAD'],['Share the correction','git push origin main','git push origin main']],insight:['Undo without erasing','Revert adds an inverse commit. Reset moves a branch pointer; --hard can discard local work. Prefer revert for shared commits.'],hint:'A revert preserves the original commit and records a correction.'}
];
lessons.forEach((item,i)=>{const guide=beginnerGuides[i];Object.assign(item,{title:guide.title,description:guide.description,insight:guide.insight,hint:guide.hint});item.steps.forEach((step,j)=>{step[0]=guide.steps[j][0];step[1]=guide.steps[j][1]});});
let lesson=0,step=0,mode='solo',view='introduction',playing=false,timer=null,commandHistory=[],historyIndex=0;let completed=[];try{completed=JSON.parse(localStorage.getItem('git-orbit-completed')||'[]');if(!Array.isArray(completed))completed=[]}catch{}let state;
function makeCommit(id,message,parent=null,branch='main',author='You'){return{id,message,parent,branch,author}}
function initialState(){return{branch:'main',commits:[makeCommit('a1c9e2','Start pancake recipe'),makeCommit('b7f3d1','Add flour and milk','a1c9e2'),makeCommit('c4e8a6','Add cooking instructions','b7f3d1')],main:'c4e8a6',feature:null,remote:'c4e8a6',tracking:'c4e8a6',working:null,staged:null,revision:0,pr:null,conflict:false,resolved:false,reverted:false}}
function resetLesson(){stopTour();step=0;state=initialState();if(lesson===4){state.feature='e9a2f5';state.main='d6c1b2';state.commits.push(makeCommit('d6c1b2','Your recipe: 1 tablespoon of sugar','c4e8a6','main'),makeCommit('e9a2f5','Maya’s recipe: 2 tablespoons of sugar','c4e8a6','feature','Maya'));state.remote=state.main;state.tracking=state.main}if(lesson===5){state.commits.push(makeCommit('d6c1b2','Accidentally remove flour','c4e8a6'));state.main=state.remote=state.tracking='d6c1b2'}$('#terminal-output').innerHTML='<div class="terminal-welcome"><span>✦</span> A fresh sandbox. Try a quick command or follow the lesson.</div>';render();}
function selectLesson(i){lesson=i;mode=i===3?'team':'solo';view='lab';resetLesson();renderView()}
function renderNav(){ $('#lesson-nav').innerHTML=lessons.map((l,i)=>`<button data-lesson="${i}" class="${i===lesson&&view==='lab'?'active':''} ${completed.includes(i)?'done':''}"><span class="number">${completed.includes(i)?'✓':String(i+1).padStart(2,'0')}</span>${l.nav}${i===lesson&&view==='lab'?'<span class="lesson-active"></span>':''}</button>`).join('');$('#overall-progress').textContent=`${completed.length} / 6`;$('#overall-bar').style.width=`${completed.length/6*100}%`;document.querySelectorAll('[data-mode]').forEach(b=>{b.classList.toggle('active',b.dataset.mode===mode);b.setAttribute('aria-selected',String(b.dataset.mode===mode))})}
function render(){renderNav();const l=lessons[lesson];$('#lesson-number').textContent=`LESSON ${String(lesson+1).padStart(2,'0')} / 06`;$('#lesson-duration').textContent=`~ ${l.duration} MIN`;$('#lesson-title').textContent=l.title;$('#lesson-description').textContent=l.description;$('#outline-count').textContent=`${l.steps.length} steps`;$('#guide-steps').innerHTML=l.steps.map((s,i)=>`<div class="guide-step ${i<step?'done':i===step?'current':''}"><span class="step-circle">${i<step?'✓':i+1}</span><div><strong>${s[0]}</strong><small>${s[1]}</small></div></div>`).join('');$('#insight-title').textContent=l.insight[0];$('#insight-text').textContent=l.insight[1];$('#next-action').innerHTML=step>=l.steps.length?'Continue to next lesson <span>✦</span>':`${l.steps[step][0]} <span>⌘</span>`;$('#lesson-step-label').textContent=step>=l.steps.length?'Lesson complete':`Step ${step+1} of ${l.steps.length}`;$('#step-dots').innerHTML=l.steps.map((_,i)=>`<i class="${i<=step?'active':''}"></i>`).join('');$('.guide-panel').classList.toggle('completed',step>=l.steps.length);$('#visual-hint').textContent=lesson===0&&step===0?'This sample already has 3 saved versions. Each circle is a commit.':l.hint;$('#terminal-branch').textContent=`(${state.branch})`;$('#head-status').innerHTML=`<i></i> Working on <code>${state.branch}</code> · HEAD`;$('#graph-title').textContent=mode==='team'?'One project. Three perspectives.':'Your repository, visualized';$('#graph-location').textContent=[2,3].includes(lesson)?'LOCAL + GITHUB':'LOCAL REPOSITORY';renderGraph();renderZones();renderChips();renderBeginnerGuide();}
function renderGraph(){const commits=state.commits;const positions=new Map();const hasFeature=commits.some(c=>c.branch==='feature');const isRemote=[2,3].includes(lesson);let mainIndex=0,featureIndex=0,remoteIndex=0;commits.forEach(c=>{if(c.branch==='main'){positions.set(c.id,{x:78+mainIndex*92,y:hasFeature?101:121});mainIndex++}else if(c.branch==='feature'){positions.set(c.id,{x:265+featureIndex*92,y:180});featureIndex++}else{positions.set(c.id,{x:365+remoteIndex*92,y:65});remoteIndex++}});const width=Math.max(580,mainIndex*92+160);const color=c=>c.branch==='feature'?'#bba2fa':c.branch==='remote'?'#75b9ff':'#63e9c3';let paths='';commits.forEach(c=>{const p=positions.get(c.id),parents=Array.isArray(c.parent)?c.parent:[c.parent];parents.filter(Boolean).forEach(pid=>{const prev=positions.get(pid);if(prev)paths+=`<path class="graph-edge" d="M${prev.x} ${prev.y} C${prev.x+45} ${prev.y} ${p.x-45} ${p.y} ${p.x} ${p.y}" fill="none" stroke="${color(c)}" stroke-width="2" opacity=".65"/>`})});let nodes=commits.map((c,i)=>{const p=positions.get(c.id);return`<g class="commit-node ${i===commits.length-1?'new-node':''}" data-commit="${c.id}" tabindex="0" role="button" aria-label="Inspect commit ${escapeHTML(c.message)}"><title>${escapeHTML(c.message)}</title><circle class="node-ring" cx="${p.x}" cy="${p.y}" r="17" fill="${color(c)}" opacity=".2"/><circle class="node-core" cx="${p.x}" cy="${p.y}" r="8" fill="#0f151d" stroke="${color(c)}" stroke-width="2"/><circle cx="${p.x}" cy="${p.y}" r="2.5" fill="${color(c)}"/><text x="${p.x}" y="${p.y+32}" text-anchor="middle" fill="#6d889c" font-size="10">Save ${i+1}</text></g>`}).join('');const label=(id,text,col,offset=0)=>{const p=positions.get(id);return p?`<g transform="translate(${p.x-30},${p.y-42-offset})"><rect width="${text.length*6.5+18}" height="21" rx="4" fill="${col}18" stroke="${col}65"/><text x="9" y="14" fill="${col}" font-size="10">${text}</text></g>`:''};let labels=label(state.main,'main','#63e9c3')+label(state.feature,'feature','#bba2fa',state.feature===state.main?29:0);if(isRemote){labels+=label(state.remote,'GitHub','#75b9ff',state.remote===state.main?29:0);if(state.tracking!==state.remote)labels+=label(state.tracking,'origin/main','#75b9ff',state.tracking===state.main?58:29)}const head=positions.get(state[state.branch]);if(head)labels+=`<text x="${head.x}" y="${head.y+54}" fill="#c1d4e2" font-size="9" text-anchor="middle">YOU ARE HERE ↓</text>`;let team=mode==='team'?'<div class="team-labels"><span class="team-person"><b>Y</b> You · developer</span><span class="team-person"><b>M</b> Maya · reviewer</span><span class="team-person"><b>L</b> Leo · teammate</span></div>':'';$('#graph').innerHTML=team+`<svg viewBox="0 0 ${width} 236" role="group" aria-label="Commit history. Main points to ${state.main}${state.feature?', feature points to '+state.feature:''}">${paths}${nodes}${labels}</svg>`;}
function renderZones(){let zones=[['▱','Working directory',state.working?'pancakes.txt':null,'Your edited files'],['◫','Staging area',state.staged?'pancakes.txt':null,'Your next snapshot'],['⑂','Repository',state[state.branch],`${state.commits.length} saved snapshots`]];if(lesson===4){zones[0][2]=state.working?'pancakes.txt':null;zones[1][2]=state.staged?'pancakes.txt':null}if(lesson===3&&state.pr)zones=[['♧','Pull request',`feature → main`,state.pr],['◫','Review',state.pr==='approved'||state.pr==='merged'?'Maya approved':null,'Waiting for Maya'],['⑂','GitHub main',state.remote,'Shared with your team']];$('#file-zones').innerHTML=zones.map((z,i)=>`<div class="file-zone ${z[2]?'active':''}"><div class="zone-title"><b>${z[0]}</b>${z[1]}<span class="zone-count">${i===2?state.commits.length:z[2]?1:0}</span></div><div class="${z[2]?'zone-file':'zone-empty'}">${z[2]||z[3]}${z[2]?'<em>'+ (i===2?'✓':i===1?'A':'M')+'</em>':''}</div></div>`).join('');const old=$('.conflict-editor');if(old)old.remove();if(lesson===4&&state.conflict){const e=document.createElement('div');e.className='conflict-editor';e.innerHTML=`<p>pancakes.txt · Choose the sugar amount, then stage the file.</p><pre>${state.resolved?`${state.resolution}`:'<<<<<<< HEAD\nSugar: 1 tablespoon\n=======\nSugar: 2 tablespoons\n>>>>>>> feature'}</pre><div class="conflict-options"><button data-resolve="Sugar: 1 tablespoon">Keep yours · 1 tablespoon</button><button data-resolve="Sugar: 2 tablespoons">Keep Maya’s · 2 tablespoons</button><button data-resolve="Sugar: 1.5 tablespoons">Agree on · 1.5 tablespoons</button></div>`;$('#file-zones').after(e)}}
function renderChips(){const sets=[['edit pancakes.txt','git status','git add pancakes.txt','git commit -m "Add chocolate chips"','git push origin main'],['git switch -c feature','git status','git switch main','git merge feature'],['git fetch origin','git status','git merge origin/main','git push origin main'],['git switch -c feature','git status','git log --oneline','git pull --ff-only origin main'],['git merge feature','git status','git add pancakes.txt','git commit -m "Agree on sugar amount"'],['git show HEAD','git revert HEAD','git log --oneline','git push origin main']];$('#command-chips').innerHTML=sets[lesson].map(c=>`<button data-command="${c.replaceAll('"','&quot;')}">${c}</button>`).join('')}
function log(message,type='info'){const line=document.createElement('div');line.className=`terminal-line ${type}`;line.textContent=message;$('#terminal-output').append(line);$('#terminal-output').scrollTop=$('#terminal-output').scrollHeight;}
function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3200)}
function advance(){step++;if(step===lessons[lesson].steps.length){if(!completed.includes(lesson)){completed.push(lesson);try{localStorage.setItem('git-orbit-completed',JSON.stringify(completed))}catch{}}toast('Lesson complete. One more part of Git makes sense.')}render()}
function addCommit(message,branch=state.branch,parents=state[branch],author='You'){const id=['d6c1b2','e9a2f5','f3b7d8','19c4e6','28d5f1','37e6a2','46f7b3','55a8c4'][state.commits.length-3]||`${state.commits.length}ab7c1`;const c=makeCommit(id,message,parents,branch,author);state.commits.push(c);if(branch==='remote')state.remote=id;else state[branch]=id;return id}
function applyStageProgress(event){const expected=lessons[lesson].steps[step]?.[2];const expectedEvent=expected?.startsWith('edit')?'edit':expected?.startsWith('git add')?'add':expected?.startsWith('git commit')?'commit':expected?.startsWith('git push')?'push':expected;if(event===expectedEvent)advance();else render()}
function execute(raw){const command=raw.trim();if(!command)return;log(`❯ ${command}`,'command');commandHistory.push(command);historyIndex=commandHistory.length;const cmd=command.replace(/\s+/g,' ');try{
if(cmd==='help'){log('Supported: edit pancakes.txt · git status · git add <file> · git commit -m "message" · git switch -c feature · git switch main · git merge feature · git fetch origin · git merge origin/main · git pull --ff-only origin main · git push origin <branch> · git log --oneline · git show HEAD · git revert HEAD · clear');return}
if(cmd==='clear'){$('#terminal-output').innerHTML='';return}
if(cmd==='git status'){log(`On branch ${state.branch}\n${state.conflict&&!state.resolved?'Unmerged paths: pancakes.txt (both modified)':state.staged?'Changes to be committed: '+'pancakes.txt':state.working?'Changes not staged for commit: pancakes.txt':'Nothing to commit, working tree clean'}${state.main!==state.remote?'\nLocal main and GitHub main point to different snapshots.':''}`);return}
if(cmd==='git log'||cmd==='git log --oneline'){let id=state[state.branch],chain=[],seen=new Set;while(id&&!seen.has(id)){seen.add(id);const c=state.commits.find(c=>c.id===id);if(!c)break;chain.push(`${c.id} ${c.message}`);id=Array.isArray(c.parent)?c.parent[0]:c.parent}log(chain.join('\n'));return}
if(cmd==='git show HEAD'){const c=state.commits.find(c=>c.id===state[state.branch]);log(`${c.id} · ${c.message}\nAuthor: ${c.author}\n${lesson===5?'− Flour: 1 cup':'A saved snapshot of the pancake recipe.'}`);if(lesson===5&&step===0)advance();return}
if(/^edit (pancakes\.txt)$/.test(cmd)){if(state.conflict)throw Error('Resolve the conflict using the choices below the graph.');state.working=++state.revision;log('Edited pancakes.txt. The saved history has not changed.','success');applyStageProgress('edit');return}
if(/^git add (pancakes\.txt|\.)$/.test(cmd)){if(state.conflict&&!state.resolved)throw Error('Choose the final sugar amount before staging the resolution.');if(!state.working)throw Error('No edited file to stage. Run edit pancakes.txt first.');state.staged=state.working;log('Staged the current file content for the next snapshot.','success');applyStageProgress('add');return}
if(/^git commit(?: -m (?:"[^"]+"|'[^']+'|\S+))?$/.test(cmd)){if(!state.staged)throw Error('Nothing staged. Edit a file and run git add first.');const msg=cmd.match(/-m ["']?(.*?)["']?$/)?.[1]||'Save changes';const parents=state.conflict?[state.main,state.feature]:state[state.branch];addCommit(msg,state.branch,parents);state.working=state.working===state.staged?null:state.working;state.staged=null;state.conflict=false;log(`Saved snapshot ${state[state.branch]}. Your commit exists locally.`, 'success');applyStageProgress('commit');return}
if(cmd==='git switch -c feature'){if(state.feature)throw Error('Branch feature already exists. Use git switch feature.');if(state.working||state.staged)throw Error('Finish the current change before starting this lesson’s feature branch.');state.feature=state[state.branch];state.branch='feature';log('Created feature at the current commit and switched HEAD to it.','success');applyStageProgress(cmd);return}
if(cmd==='git switch main'||cmd==='git switch feature'){if(state.conflict)throw Error('Resolve or finish the merge before switching.');if(state.working||state.staged)throw Error('Commit your current changes before switching in this sandbox.');const b=cmd.split(' ')[2];if(!state[b])throw Error(`Branch ${b} does not exist. Create it with git switch -c feature.`);state.branch=b;log(`Switched to ${b}. HEAD follows ${b}.`,'success');applyStageProgress(cmd);return}
if(cmd==='git merge feature'){if(state.branch!=='main')throw Error('Switch to main before merging feature.');if(!state.feature)throw Error('Create and commit on feature first.');if(state.conflict)throw Error('A merge is already in progress. Resolve, stage, and commit.');if(lesson===4&&!state.resolved){state.conflict=true;state.working='conflict';log('CONFLICT: both branches changed pancakes.txt. Git paused the merge. Choose a result below the graph.','error');applyStageProgress(cmd);return}if(state.main===state.feature){log('Already up to date.');return}const feature=state.commits.find(c=>c.id===state.feature);if(feature.parent===state.main){state.main=state.feature;log('Fast-forward: main moved to the feature snapshot. No merge commit was needed.','success')}else{addCommit('Merge feature','main',[state.main,state.feature]);log('Created a merge commit with two parents.','success')}applyStageProgress(cmd);return}
if(cmd==='git fetch origin'){state.tracking=state.remote;log('Downloaded remote history. origin/main now points to GitHub main; your local main did not move.','success');applyStageProgress(cmd);return}
if(cmd==='git merge origin/main'){if(state.branch!=='main')throw Error('Switch to main for this lesson.');if(state.tracking===state.main){log('Already up to date. Run git fetch origin to discover remote updates.');return}if(!isAncestor(state.main,state.tracking))throw Error('Histories have diverged. This lesson uses a fast-forward; reset to replay it.');state.main=state.tracking;log('Fast-forwarded main to origin/main. Your working files now include the update.','success');applyStageProgress(cmd);return}
if(/^git pull(?: --ff-only)? origin main$/.test(cmd)){if(state.branch!=='main')throw Error('Switch to main before pulling in this lesson.');if(!isAncestor(state.main,state.remote))throw Error('Cannot fast-forward: local and remote histories have diverged.');state.tracking=state.remote;state.main=state.remote;log('Fetched origin, then fast-forwarded local main to GitHub main.','success');if(lesson===3&&step===5)advance();else if(lesson===2&&step===2)advance();else render();return}
if(/^git push(?: -u)? origin (main|feature)$/.test(cmd)){const b=cmd.split(' ').at(-1);if(!state[b])throw Error(`Branch ${b} does not exist.`);if(b==='main'){if(!isAncestor(state.remote,state.main))throw Error('Push rejected: fetch and integrate the remote changes first.');state.remote=state.main;state.tracking=state.main}log(`Published ${b} to GitHub. Your local branch stays in place.`,'success');applyStageProgress('push');return}
if(cmd==='git revert HEAD'){if(state.working||state.staged)throw Error('Commit current changes before reverting.');if(state.reverted)throw Error('The mistake is already reverted in this lesson.');if(lesson!==5)throw Error('Open Undo & recovery to practice reverting a published mistake.');addCommit('Revert "Accidentally remove flour"');state.reverted=true;log('Added an inverse commit. The flour line is restored and the original history remains.','success');applyStageProgress(cmd);return}
throw Error('That command is outside this learning sandbox. Type help for supported commands.');
}catch(e){log(e.message,'error');toast(e.message)}finally{render()}}
function isAncestor(ancestor,descendant){if(ancestor===descendant)return true;const c=state.commits.find(c=>c.id===descendant);return!!c&&(Array.isArray(c.parent)?c.parent:[c.parent]).filter(Boolean).some(p=>isAncestor(ancestor,p))}
function performAction(){if(step>=lessons[lesson].steps.length){selectLesson((lesson+1)%lessons.length);return}const action=lessons[lesson].steps[step][2];if(action==='build-feature'){execute('edit pancakes.txt');execute('git add pancakes.txt');execute('git commit -m "Add chocolate chips"');if(step===1)advance();return}if(action==='remote-change'){log('Leo: edit → stage → commit → push on GitHub main.','command');addCommit('Leo clarifies mixing instructions','remote',state.remote,'Leo');log('GitHub has a new snapshot. Your local main has not changed.','success');advance();return}if(action==='publish-change'){execute('edit pancakes.txt');execute('git add pancakes.txt');execute('git commit -m "Clarify pancake instructions"');execute('git push origin main');if(step===3)advance();return}if(action==='team-push'){if(state.branch!=='feature'){toast('Switch to feature before publishing your work.');return}execute('edit pancakes.txt');execute('git add pancakes.txt');execute('git commit -m "Add chocolate chips"');execute('git push -u origin feature');if(step===1)advance();return}if(action==='open-pr'){state.pr='open';log('GitHub: opened pull request #1 · feature → main.','command');log('Maya can inspect the diff, discuss changes, and review the proposal.');advance();return}if(action==='review-pr'){state.pr='approved';addCommit('Leo clarifies mixing instructions','remote',state.remote,'Leo');log('Leo pushed an independent update to GitHub main. Your feature keeps its own history.');log('Maya reviewed your diff and approved pull request #1.','success');advance();return}if(action==='merge-pr'){const id=addCommit('Merge pull request #1','remote',[state.remote,state.feature],'Maya');state.remote=id;state.pr='merged';state.branch='main';log('GitHub created a merge commit. Your local main still needs to be updated.','success');advance();return}if(action==='team-pull'){execute('git pull --ff-only origin main');return}if(action==='resolve-conflict'){toast('Choose a sugar amount below the graph, then continue.');$('.conflict-editor')?.scrollIntoView({behavior:'smooth',block:'nearest'});return}execute(action)}
function resolveConflict(value){state.resolved=true;state.resolution=value;state.working='resolved';log(`Resolved pancakes.txt: ${value}`,'success');if(step===1)advance();else render()}
function inspectCommit(id){const c=state.commits.find(c=>c.id===id);if(!c)return;openDialog(`<div class="detail-label">COMMIT SNAPSHOT</div><h2>${escapeHTML(c.message)}</h2><p><code>${c.id}</code> · ${c.author}</p><p>Parent${Array.isArray(c.parent)?'s':''}: <code>${Array.isArray(c.parent)?c.parent.join(' + '):c.parent||'None — the first commit'}</code></p><p>${Array.isArray(c.parent)?'This merge commit joins two lines of history.':'This snapshot belongs to the repository history. Branch labels can move; the saved snapshot stays the same.'}</p><p>Follow the lesson’s commands to see how branch pointers move.</p>`)}
function openDialog(html){$('#detail-content').innerHTML=html;$('#detail-dialog').showModal()}
function stopTour(){playing=false;clearTimeout(timer);if($('#tour'))$('#tour').innerHTML='<span>▷</span> Play walkthrough'}
function tickTour(){if(!playing)return;if(step>=lessons[lesson].steps.length){stopTour();return}if(lesson===4&&step===1)resolveConflict('Sugar: 1.5 tablespoons');else performAction();timer=setTimeout(tickTour,2400)}
function toggleTour(){if(playing){stopTour();return}if(step>=lessons[lesson].steps.length)resetLesson();playing=true;$('#tour').innerHTML='<span>Ⅱ</span> Pause walkthrough';tickTour()}
function renderView(){renderNav();$('#introduction-view').hidden=view!=='introduction';$('.intro h1').innerHTML=view==='introduction'?'Every project has a <span>story.</span>':'Make sense of <span>Git.</span>';$('.intro>div>p').textContent=view==='introduction'?'Start with a familiar idea. Learn the Git words as you go.':'Follow the buttons. Understand the action. Then try the command.';document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view));$('#lab-view').hidden=view!=='lab';$('#reference-view').hidden=view!=='reference';$('#challenge-view').hidden=view!=='challenge';$('.workspace-tabs').hidden=view!=='lab';$('#tour').hidden=view!=='lab';$('#breadcrumb').textContent=view==='introduction'?'Introduction':view==='lab'?'Learning lab':view==='reference'?'Command reference':'Practice challenges';if(view==='introduction')renderIntroduction();if(view==='reference')renderReference();if(view==='challenge')renderChallenges();}
const commands=[['git init','Turn a folder into a Git repository.','Run once when starting a new local project.',0],['git clone <url>','Download a repository and its history.','Creates a local copy with origin configured.',2],['git status','Inspect your branch, staged changes, and unstaged changes.','A useful first step whenever you feel lost.',0],['git diff','See the changes between working files and the staging area.','Use git diff --staged to inspect your next commit.',0],['git add <file>','Stage the file’s current content for the next snapshot.','If you edit it again, stage it again to include that edit.',0],['git commit -m "message"','Record the staged snapshot in your local history.','A commit does not publish anything to GitHub.',0],['git switch -c feature','Create a branch and start working on it.','The new branch initially points to your current commit.',1],['git switch main','Switch your working files and HEAD to main.','Save or stash changes before switching when necessary.',1],['git merge feature','Integrate feature into your current branch.','Can fast-forward, create a merge commit, or stop at conflicts.',1],['git fetch origin','Download history and refresh remote-tracking branches.','Does not integrate changes into your current branch.',2],['git pull --ff-only origin main','Fetch and update your current branch only if it can fast-forward.','Diverged branches require an explicit merge or rebase decision.',2],['git push -u origin feature','Publish feature and set its upstream tracking branch.','Push can be rejected if the remote has incompatible updates.',3],['git log --oneline','Read the commits reachable from your current branch.','Each short ID identifies a saved snapshot.',0],['git revert HEAD','Create a new commit that reverses the latest commit.','Suitable for undoing a mistake in shared history.',5],['git restore <file>','Discard unstaged edits in a tracked file.','Destructive: check git diff first. Not simulated here.',5],['git restore --staged <file>','Remove a file’s changes from the staging area.','Keeps the edits in your working directory.',0],['git stash','Temporarily save local changes for later.','Use git stash pop to reapply them; conflicts can occur.',1],['git reset --soft HEAD~1','Move the branch back one commit, keeping changes staged.','Rewrites the local branch. Avoid changing shared history.',5]];
function escapeHTML(s){return s.replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;')}
function renderReference(){ $('#reference-view').innerHTML='<h2>A command for every moment.</h2><input class="reference-search" id="reference-search" placeholder="Search commands or what you want to do…" aria-label="Search command reference"><div class="reference-grid" id="reference-grid"></div>';filterReference('');$('#reference-search').addEventListener('input',e=>filterReference(e.target.value))}
function filterReference(q){const matches=commands.filter(c=>c.join(' ').toLowerCase().includes(q.toLowerCase()));$('#reference-grid').innerHTML=matches.length?matches.map(c=>`<article class="reference-card"><code>${escapeHTML(c[0])}</code><p>${c[1]}</p><small>${c[2]}</small><br><button data-lesson="${c[3]}">Explore this lesson</button></article>`).join(''):'<p>No matching commands. Try “stage”, “branch”, or “undo”.</p>'}
const quizzes=[{name:'Which recipe version gets saved?',tag:'01 · FUNDAMENTALS',desc:'You edit the recipe again after staging it. Which recipe content will the next commit save?',answers:['The version you staged.','Every edit in the working directory.','The current version on GitHub.'],correct:0,why:'git add captures the content at that moment. Later edits stay unstaged until you add them again.',lesson:0},{name:'Fetch or pull?',tag:'02 · REMOTES',desc:'You want to inspect Leo’s recipe update before changing your own branch. What do you run?',answers:['git pull origin main','git fetch origin','git push origin main'],correct:1,why:'Fetch downloads the remote history and updates origin/main. Your working files and local main stay in place.',lesson:2},{name:'Undo without surprises',tag:'03 · TEAMWORK',desc:'A recipe mistake is already shared with your team. How do you undo it while keeping the earlier versions?',answers:['Delete the repository.','git reset --hard HEAD~1 and force push','git revert HEAD'],correct:2,why:'Revert records the inverse change as a new commit. Your teammates can pull the correction without rewriting shared history.',lesson:5}];
function renderChallenges(){ $('#challenge-view').innerHTML='<h2>Put your mental model to the test.</h2><p class="challenge-header">Three quick scenarios. Make a prediction, get an explanation, then explore it in the lab.</p><div class="challenge-list">'+quizzes.map((q,i)=>`<article class="challenge-card"><span>${q.tag}</span><h3>${q.name}</h3><p>${q.desc}</p><button class="primary-button" data-quiz="${i}">Take the challenge <span>⚑</span></button></article>`).join('')+'</div>'}
function openQuiz(i){const q=quizzes[i];openDialog(`<div class="detail-label">${q.tag}</div><h2>${q.name}</h2><p>${q.desc}</p><div class="quiz-options">${q.answers.map((a,j)=>`<button data-answer="${j}" data-quizid="${i}">${escapeHTML(a)}</button>`).join('')}</div><div class="quiz-result" id="quiz-result" aria-live="polite"></div><button class="quiet-button" data-quizlesson="${q.lesson}">Explore in the lab</button>`)}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.lesson!==undefined)selectLesson(Number(b.dataset.lesson));if(b.dataset.view){stopTour();view=b.dataset.view;renderView()}if(b.dataset.mode){selectLesson(b.dataset.mode==='team'?3:0)}if(b.dataset.command){execute(b.dataset.command);$('#command-input').focus()}if(b.dataset.resolve)resolveConflict(b.dataset.resolve);if(b.dataset.quiz!==undefined)openQuiz(Number(b.dataset.quiz));if(b.dataset.answer!==undefined){const q=quizzes[Number(b.dataset.quizid)];$('#quiz-result').textContent=(Number(b.dataset.answer)===q.correct?'Exactly. ':'Try again. ')+q.why}if(b.dataset.quizlesson){$('#detail-dialog').close();selectLesson(Number(b.dataset.quizlesson))}});
$('#graph').addEventListener('click',e=>{const n=e.target.closest('[data-commit]');if(n)inspectCommit(n.dataset.commit)});$('#graph').addEventListener('keydown',e=>{const n=e.target.closest('[data-commit]');if(n&&['Enter',' '].includes(e.key)){e.preventDefault();inspectCommit(n.dataset.commit)}});
$('#terminal-form').addEventListener('submit',e=>{e.preventDefault();stopTour();execute($('#command-input').value);$('#command-input').value=''});$('#command-input').addEventListener('keydown',e=>{if(e.key==='ArrowUp'){e.preventDefault();historyIndex=Math.max(0,historyIndex-1);e.target.value=commandHistory[historyIndex]||''}if(e.key==='ArrowDown'){e.preventDefault();historyIndex=Math.min(commandHistory.length,historyIndex+1);e.target.value=commandHistory[historyIndex]||''}});
$('#next-action').addEventListener('click',()=>{stopTour();performAction()});$('#reset').addEventListener('click',()=>{resetLesson();toast('Sandbox reset. Your learning progress is kept.')});$('#tour').addEventListener('click',toggleTour);$('.dialog-close').addEventListener('click',()=>$('#detail-dialog').close());$('#detail-dialog').addEventListener('click',e=>{if(e.target===$('#detail-dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close()}});
$('#motion-toggle').addEventListener('click',()=>{const paused=document.body.classList.toggle('motion-paused');$('#motion-toggle').setAttribute('aria-label',paused?'Resume decorative motion':'Pause decorative motion');$('#motion-toggle').title=paused?'Resume decorative motion':'Pause decorative motion';toast(paused?'Decorative motion paused':'Decorative motion resumed')});$('#help').addEventListener('click',()=>openDialog('<div class="detail-label">WELCOME TO GIT ORBIT</div><h2>Learn one visible step at a time.</h2><p>New to Git? Open Introduction to try a pancake recipe example. Then follow a lesson with the mint button, play an animated walkthrough, or type commands in the sandbox. Click any commit to see its snapshot and parents.</p><p>This is a simplified learning simulator. It does not execute shell commands or connect to a real GitHub account. Short commit IDs are illustrative. Pull requests and reviews are simulated.</p><p>Progress stays in this browser. Use the motion control to pause decorative animation; your device’s reduced-motion preference is also respected.</p><p>Go deeper with the <a href="https://git-scm.com/book/en/v2" target="_blank" rel="noreferrer">Pro Git book</a> and <a href="https://docs.github.com/en/pull-requests/get-started/about-pull-requests" target="_blank" rel="noreferrer">GitHub pull request guide</a>.</p>'));
document.addEventListener('keydown',e=>{if(e.key.toLowerCase()==='l'&&!['INPUT','TEXTAREA'].includes(e.target.tagName)&&!$('#detail-dialog').open){view='lab';renderView()}});resetLesson();renderView();

// Structured access uses the same actions and visible state as the learning lab.
if(document.modelContext?.registerTool){
 const lifecycle=new AbortController();
 const readState=()=>({lesson:lesson+1,title:lessons[lesson].title,step:Math.min(step+1,lessons[lesson].steps.length),complete:step>=lessons[lesson].steps.length,branch:state.branch,main:state.main,feature:state.feature,remote:state.remote,staged:!!state.staged,edited:!!state.working,conflict:state.conflict});
 const registrations=[
 {name:'read_git_lab_state',title:'Read Git lab state',description:'Read the current simulated repository and lesson progress.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:false},execute:()=>readState()},
 {name:'start_git_lesson',title:'Start a Git lesson',description:'Reset the sandbox and open lesson 1–6: fundamentals, branches, remotes, teams, conflicts, or recovery.',inputSchema:{type:'object',properties:{lesson:{type:'integer',minimum:1,maximum:6}},required:['lesson'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute:input=>{if(!input||!Number.isInteger(input.lesson)||input.lesson<1||input.lesson>6)throw Error('Lesson must be an integer from 1 to 6.');selectLesson(input.lesson-1);return readState()}},
 {name:'advance_git_lesson',title:'Perform the next lesson action',description:'Perform the current guided sandbox action. Conflict resolution requires choosing final file content in the visible lab.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute:()=>{stopTour();performAction();return readState()}}
 ];
 for(const tool of registrations){try{Promise.resolve(document.modelContext.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{})}catch{}}
 window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});
}
